import{_ as n,C as s,o as i,c,aj as r,E as e,j as o,a}from"./framework.js";const _=JSON.parse('{"title":"Cookie | Cms / Settings | Documentation","description":"Cookie 管理用于配置访客前台看到的 Cookie 同意弹窗：启用范围、显示样式、多语言文案、Cookie 分类、外部资源归类与同意统计。后台保存的是站点级 CookieConsentSetting；前台读写单个 Cookie 的脚本能力请看 k.cookie。","frontmatter":{"title":"Cookie | Cms / Settings | Documentation","description":"Cookie 管理用于配置访客前台看到的 Cookie 同意弹窗：启用范围、显示样式、多语言文案、Cookie 分类、外部资源归类与同意统计。后台保存的是站点级 CookieConsentSetting；前台读写单个 Cookie 的脚本能力请看 k.cookie。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/settings/cookie.html"}]]},"headers":[],"relativePath":"zh/cms/settings/cookie.md","filePath":"cms/settings/cookie.md","lastUpdated":1780977342000}'),h={name:"zh/cms/settings/cookie.md"};function g(l,t,k,b,C,m){const d=s("DocImage");return i(),c("div",null,[t[0]||(t[0]=r('<h1 id="cookie" tabindex="-1">Cookie <a class="header-anchor" href="#cookie" aria-label="Permalink to &quot;Cookie&quot;">​</a></h1><blockquote><p>菜单：<strong>站点设置 → Cookie 管理</strong><br> 深链：<code>/_Admin/system/cookie?SiteId={站点GUID}</code><br> Tab 深链：<code>tab=basic</code> / <code>categories</code> / <code>content</code> / <code>scripts</code> / <code>reports</code></p></blockquote><p><strong>Cookie 管理</strong>用于配置访客前台看到的 Cookie 同意弹窗：启用范围、显示样式、多语言文案、Cookie 分类、外部资源归类与同意统计。后台保存的是站点级 <code>CookieConsentSetting</code>；前台读写单个 Cookie 的脚本能力请看 <a href="/kb-docs/zh/api/cookie/">k.cookie</a>。</p><div class="tip custom-block"><p class="custom-block-title">权限</p><table tabindex="0"><thead><tr><th>操作</th><th>权限</th></tr></thead><tbody><tr><td>打开 <strong>Cookie 管理</strong> 页面</td><td><code>site·edit</code></td></tr><tr><td>底部 <strong>保存</strong>、<strong>保存并预览</strong></td><td><code>site·edit</code></td></tr><tr><td>添加 / 编辑分类、内容、资源与 Cookie 项</td><td><code>site·edit</code>（先写入当前表单，仍需底部保存）</td></tr><tr><td>资源管理列表 <strong>多选删除</strong></td><td>页面仍需 <code>site·edit</code>，删除按钮额外检查 <code>cookie·delete</code></td></tr></tbody></table></div><div class="warning custom-block"><p class="custom-block-title">保存机制</p><p>分类、资源、Cookie 项弹窗里的 <strong>保存 / 创建</strong> 只把改动写回当前页面表单。离开页面前，请再点底部 <strong>保存</strong>；要立即检查前台效果，点 <strong>保存并预览</strong>，系统会保存后用站点 <a href="./basic/general.html#站点信息">Base URL</a> 打开新标签页。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>站点设置 → Cookie 管理</strong>。</li><li>左侧 <strong>站点设置 → Cookie 管理</strong>。</li></ol>',7)),e(d,{src:"/cms/settings/settings-cookie-overview.png",alt:"Cookie 管理基础设置",width:"1120"}),t[1]||(t[1]=o("h2",{id:"页面结构",tabindex:"-1"},[a("页面结构 "),o("a",{class:"header-anchor",href:"#页面结构","aria-label":'Permalink to "页面结构"'},"​")],-1)),t[2]||(t[2]=o("p",null,[a("Cookie 管理按 Tab 组织，切换时 URL 会写入 "),o("code",null,"tab"),a(" 参数。")],-1)),e(d,{src:"/cms/settings/settings-cookie-tabs.png",alt:"Cookie 管理 Tab",width:"1120"}),t[3]||(t[3]=r('<table tabindex="0"><thead><tr><th>Tab</th><th>用途</th><th>是否显示底部保存</th></tr></thead><tbody><tr><td><strong>基础设置</strong></td><td>启用开关、关闭按钮、重新打开方式、显示地区、Banner 模板</td><td>是</td></tr><tr><td><strong>Cookie 分类</strong></td><td>维护必要 / 可选 Cookie 分类与默认勾选</td><td>是</td></tr><tr><td><strong>内容配置</strong></td><td>维护同意弹窗的多语言文案、按钮与政策链接</td><td>是</td></tr><tr><td><strong>资源管理</strong></td><td>将外部资源绑定到分类，并登记该资源产生的 Cookie</td><td>是</td></tr><tr><td><strong>数据报表</strong></td><td>按日期查看同意决策与分类趋势</td><td>否</td></tr></tbody></table><h2 id="基础设置" tabindex="-1">基础设置 <a class="header-anchor" href="#基础设置" aria-label="Permalink to &quot;基础设置&quot;">​</a></h2><p>基础设置建议最后确认：先配好分类、文案与资源，再开启并预览。</p>',3)),e(d,{src:"/cms/settings/settings-cookie-basic.png",alt:"Cookie 基础设置",width:"1120"}),t[4]||(t[4]=r('<h3 id="启用与关闭按钮" tabindex="-1">启用与关闭按钮 <a class="header-anchor" href="#启用与关闭按钮" aria-label="Permalink to &quot;启用与关闭按钮&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>启用 Cookie 管理</strong></td><td>开启后前台输出 Cookie 同意弹窗；关闭时不显示</td></tr><tr><td><strong>显示关闭按钮</strong></td><td>控制弹窗右上角是否显示关闭入口</td></tr><tr><td><strong>关闭行为</strong></td><td>用户未明确选择时关闭弹窗的处理：<strong>同意</strong>、<strong>拒绝</strong>、或 <strong>根据地区法律规定（默认）</strong></td></tr></tbody></table><h3 id="面板重启方式" tabindex="-1">面板重启方式 <a class="header-anchor" href="#面板重启方式" aria-label="Permalink to &quot;面板重启方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>自定义</strong></td><td>前台页面自行放置带 <code>kc-reopen-btn</code> class 的元素，访客点击后重新打开 Cookie 设置面板</td></tr><tr><td><strong>悬浮小球</strong></td><td>前台右下角自动显示一个悬浮按钮，用于重新打开面板</td></tr></tbody></table><p>若需要让运营在后台维护自定义按钮的文字或链接，可将按钮所在 HTML 做成 <a href="./../content/tag-attributes.html">元素属性</a> 或模板资源，再由前台模板输出。</p><h3 id="显示规则" tabindex="-1">显示规则 <a class="header-anchor" href="#显示规则" aria-label="Permalink to &quot;显示规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td><strong>全部地区</strong></td><td>所有访客都显示同意弹窗</td></tr><tr><td><strong>欧盟地区</strong></td><td>只在欧盟地区显示</td></tr><tr><td><strong>自定义地区</strong></td><td>选择 <strong>包含规则</strong> 或 <strong>排除规则</strong>，再从国家列表中勾选国家</td></tr></tbody></table><p>自定义国家列表来自后台国家接口，按大洲分组展示。</p><h3 id="banner-模板" tabindex="-1">Banner 模板 <a class="header-anchor" href="#banner-模板" aria-label="Permalink to &quot;Banner 模板&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模板</th><th>配置项</th></tr></thead><tbody><tr><td><strong>默认模板</strong></td><td>选择 <strong>弹窗类型和位置</strong>，并在 <strong>浅色 / 深色 / 自定义</strong> 主题中选择样式；自定义主题可设置主色、背景色、文字色、按钮色与按钮文字色</td></tr><tr><td><strong>自定义模板</strong></td><td>使用 HTML 编辑器维护完整模板片段；建议从系统生成的精简模板改起，保留必要 ID 与 <code>data-*</code> 属性</td></tr></tbody></table><h4 id="自定义模板的目标" tabindex="-1">自定义模板的目标 <a class="header-anchor" href="#自定义模板的目标" aria-label="Permalink to &quot;自定义模板的目标&quot;">​</a></h4><p>自定义模板主要解决 <strong>视觉、布局、文案组织与品牌化</strong>：例如把底部 Banner 改成侧边浮层、调整按钮顺序、增加品牌说明、重排 Cookie 分类与详情区域。它不需要重新实现 Cookie 同意逻辑；保存状态、按钮事件、分类同步、外部资源恢复与统计上报都由系统内置前台脚本处理。</p><p>前台加载顺序如下：</p><table tabindex="0"><thead><tr><th>步骤</th><th>系统行为</th><th>开发者需要做什么</th></tr></thead><tbody><tr><td>1</td><td>后台保存 <code>CookieConsentSetting</code></td><td>在本页配置分类、文案、资源和模板</td></tr><tr><td>2</td><td>前台请求 <code>/_api/cj/client</code></td><td>系统把自定义模板先按 <a href="/kb-docs/zh/templateEngine/">Kooboo 模板语法</a> 渲染成 HTML</td></tr><tr><td>3</td><td>内置脚本把模板注入页面</td><td>模板中保留必要容器、按钮 ID 与分类 checkbox</td></tr><tr><td>4</td><td>访客点击同意按钮</td><td>内置脚本写入同意 Cookie、恢复允许的资源并记录统计</td></tr></tbody></table><h4 id="模板可依赖的数据" tabindex="-1">模板可依赖的数据 <a class="header-anchor" href="#模板可依赖的数据" aria-label="Permalink to &quot;模板可依赖的数据&quot;">​</a></h4><p>模板渲染时可读取当前站点 Cookie 配置，常用信息来自后台这几个区域：</p><table tabindex="0"><thead><tr><th>后台区域</th><th>模板中通常用于</th></tr></thead><tbody><tr><td><strong>Cookie 分类</strong></td><td>渲染分类名称、描述、必需状态、默认勾选状态</td></tr><tr><td><strong>内容配置</strong></td><td>渲染标题、描述、介绍、按钮文案、隐私政策与 Cookie 政策链接</td></tr><tr><td><strong>资源管理</strong></td><td>在详情页展示某分类关联的资源与 Cookie 项</td></tr><tr><td><strong>基础设置</strong></td><td>判断关闭按钮、悬浮小球、弹窗类型与位置</td></tr></tbody></table><p>不建议在模板里硬编码分类 ID 以外的业务文案；多语言站点应优先使用 <strong>内容配置</strong> 与 <strong>Cookie 分类</strong> 中的多语言字段。</p><h4 id="必须保留的-dom-约定" tabindex="-1">必须保留的 DOM 约定 <a class="header-anchor" href="#必须保留的-dom-约定" aria-label="Permalink to &quot;必须保留的 DOM 约定&quot;">​</a></h4><p>内置脚本通过下列 ID 或属性绑定事件。开发者可以调整标签类型、层级和样式，但这些标识要保留，且同一 ID 不要重复。</p><table tabindex="0"><thead><tr><th>标识</th><th>作用</th></tr></thead><tbody><tr><td><code>kb-cookie-banner</code></td><td>Banner 容器；系统控制显示 / 隐藏</td></tr><tr><td><code>kb-cookie-accept-all</code></td><td>Banner 中 <strong>接受全部</strong></td></tr><tr><td><code>kb-cookie-save</code></td><td>Banner 中 <strong>保存当前选择</strong></td></tr><tr><td><code>kb-cookie-reject</code></td><td>Banner 中 <strong>拒绝非必要 Cookie</strong></td></tr><tr><td><code>kb-cookie-settings</code></td><td>从 Banner 打开设置弹窗</td></tr><tr><td><code>kb-cookie-close</code></td><td>Banner 关闭按钮；行为受 <strong>关闭行为</strong> 配置影响</td></tr><tr><td><code>kb-cookie-modal</code></td><td>设置弹窗容器</td></tr><tr><td><code>kb-cookie-modal-overlay</code></td><td>弹窗遮罩</td></tr><tr><td><code>kb-cookie-modal-close</code></td><td>关闭设置弹窗</td></tr><tr><td><code>kb-cookie-modal-accept-all</code></td><td>弹窗中 <strong>接受全部</strong></td></tr><tr><td><code>kb-cookie-modal-save</code></td><td>弹窗中 <strong>保存当前选择</strong></td></tr><tr><td><code>kb-cookie-modal-reject</code></td><td>弹窗中 <strong>拒绝非必要 Cookie</strong></td></tr><tr><td><code>data-category-id=&quot;{分类ID}&quot;</code></td><td>分类 checkbox；系统同步勾选状态并读取访客选择</td></tr><tr><td><code>data-tab</code> / <code>data-tab-content</code></td><td>设置弹窗内 Tab 切换</td></tr><tr><td><code>data-expand-category</code> / <code>data-resources-category</code></td><td>分类详情展开与资源列表区域</td></tr><tr><td><code>kc-reopen-btn</code></td><td>自定义重新打开按钮的 class；当不用悬浮小球时放在前台页面任意位置</td></tr></tbody></table><p>若只做轻度品牌化，优先改 CSS、文案布局和按钮顺序；若重构 DOM，请先保留上表所有关键标识，再逐项删减验证。</p><h4 id="内置脚本会接管的行为" tabindex="-1">内置脚本会接管的行为 <a class="header-anchor" href="#内置脚本会接管的行为" aria-label="Permalink to &quot;内置脚本会接管的行为&quot;">​</a></h4><table tabindex="0"><thead><tr><th>行为</th><th>说明</th></tr></thead><tbody><tr><td>首次访问展示</td><td>根据 <code>typeAndPosition</code> 决定显示 Banner、弹窗或内联区域</td></tr><tr><td>分类勾选同步</td><td>同一分类可能同时出现在 Banner 与弹窗，系统按 <code>data-category-id</code> 同步状态</td></tr><tr><td>必要分类保护</td><td>必需分类固定启用，访客不能取消</td></tr><tr><td>同意状态保存</td><td>系统写入 <code>kb_cookie_consent</code>，再次访问按已保存状态决定是否展示</td></tr><tr><td>资源恢复</td><td>未同意前被改写为 <code>kc-src</code> / <code>kc-href</code> 的资源，会在分类同意后恢复为真实 <code>src</code> / <code>href</code></td></tr><tr><td>Iframe 占位</td><td>未同意时 iframe 显示 <strong>Iframe 占位内容</strong>，同意后恢复原始地址</td></tr><tr><td>统计上报</td><td>访客提交同意结果后写入 Cookie 同意统计，供 <strong>数据报表</strong> 使用</td></tr></tbody></table><p>因此，自定义模板一般不要自行写入同意 Cookie、主动加载受控第三方资源，或绕过 <a href="#资源管理">资源管理</a> 的分类配置。</p><h4 id="开发检查清单" tabindex="-1">开发检查清单 <a class="header-anchor" href="#开发检查清单" aria-label="Permalink to &quot;开发检查清单&quot;">​</a></h4><table tabindex="0"><thead><tr><th>检查项</th><th>说明</th></tr></thead><tbody><tr><td>按钮 ID</td><td>接受全部、保存选择、拒绝、设置、关闭按钮都能触发</td></tr><tr><td>分类 checkbox</td><td>每个可选分类都有 <code>data-category-id</code>，必要分类显示为不可取消</td></tr><tr><td>重新打开入口</td><td>悬浮小球或 <code>kc-reopen-btn</code> 至少保留一种</td></tr><tr><td>移动端</td><td>Banner、弹窗、按钮组在手机宽度下不遮挡正文</td></tr><tr><td>资源恢复</td><td>拒绝后第三方资源不加载；同意对应分类后资源恢复</td></tr><tr><td>多语言</td><td>切换站点语言后标题、按钮、分类与政策链接正确</td></tr></tbody></table><h2 id="cookie-分类" tabindex="-1">Cookie 分类 <a class="header-anchor" href="#cookie-分类" aria-label="Permalink to &quot;Cookie 分类&quot;">​</a></h2><p>分类决定访客可以选择哪些 Cookie 类型，也会被资源管理和数据报表引用。</p>',29)),e(d,{src:"/cms/settings/settings-cookie-categories.png",alt:"Cookie 分类",width:"1120"}),t[5]||(t[5]=r('<table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td><strong>添加分类</strong></td><td>打开添加分类弹窗，按站点支持语言填写名称与描述</td></tr><tr><td><strong>多语言选择器</strong></td><td>切换当前编辑语言；语言列表来自站点多语言配置</td></tr><tr><td><strong>分类卡片</strong></td><td>必要分类排在前面，可选分类排在后面</td></tr><tr><td><strong>必需 / 可选</strong></td><td>必要分类不可取消默认选中；可选分类可删除</td></tr><tr><td><strong>默认选中</strong></td><td>访客首次打开弹窗时该分类是否预先勾选；必要分类固定选中</td></tr></tbody></table>',1)),e(d,{src:"/cms/settings/settings-cookie-add-category-dialog.png",alt:"添加 Cookie 分类",width:"1120"}),t[6]||(t[6]=o("p",null,[a("新增分类默认是 "),o("strong",null,"可选"),a(" 且未默认选中。创建后仍在当前表单内，需点页面底部 "),o("strong",null,"保存"),a(" 才写入站点。")],-1)),t[7]||(t[7]=o("h2",{id:"内容配置",tabindex:"-1"},[a("内容配置 "),o("a",{class:"header-anchor",href:"#内容配置","aria-label":'Permalink to "内容配置"'},"​")],-1)),t[8]||(t[8]=o("p",null,"内容配置维护访客看到的文字。若站点开启多语言，请逐个语言检查。",-1)),e(d,{src:"/cms/settings/settings-cookie-content.png",alt:"Cookie 内容配置",width:"1120"}),t[9]||(t[9]=r('<table tabindex="0"><thead><tr><th>字段</th><th>显示位置</th></tr></thead><tbody><tr><td><strong>标题</strong></td><td>Cookie 弹窗标题</td></tr><tr><td><strong>描述</strong></td><td>弹窗主说明</td></tr><tr><td><strong>介绍</strong></td><td>Cookie 设置面板的介绍区域</td></tr><tr><td><strong>接受全部</strong></td><td>同意全部 Cookie 的按钮文案</td></tr><tr><td><strong>接受所选</strong></td><td>仅保存当前勾选分类的按钮文案</td></tr><tr><td><strong>拒绝全部</strong></td><td>拒绝非必要 Cookie 的按钮文案</td></tr><tr><td><strong>隐私政策链接</strong></td><td>隐私政策 URL 与链接文本</td></tr><tr><td><strong>Cookie 政策链接</strong></td><td>Cookie 政策 URL 与链接文本</td></tr><tr><td><strong>Iframe 占位内容</strong></td><td>访客尚未同意对应分类时，iframe 位置显示的占位 HTML</td></tr></tbody></table><h2 id="资源管理" tabindex="-1">资源管理 <a class="header-anchor" href="#资源管理" aria-label="Permalink to &quot;资源管理&quot;">​</a></h2><p>资源管理用于告诉系统：某个外部 <code>script</code>、<code>img</code>、<code>iframe</code> 或 <code>link</code> 属于哪个 Cookie 分类，以及它可能写入哪些 Cookie。</p>',3)),e(d,{src:"/cms/settings/settings-cookie-scripts.png",alt:"Cookie 资源管理",width:"1120"}),t[10]||(t[10]=r('<h3 id="资源列表" tabindex="-1">资源列表 <a class="header-anchor" href="#资源列表" aria-label="Permalink to &quot;资源列表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列 / 操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td>外部资源地址</td></tr><tr><td><strong>分类</strong></td><td>资源所属 Cookie 分类</td></tr><tr><td><strong>展开行</strong></td><td>查看该资源下登记的 Cookie；可 <strong>添加 Cookie</strong>、编辑或删除 Cookie 项</td></tr><tr><td><strong>编辑</strong></td><td>打开资源弹窗，调整 URL、资源类型、分类与 Cookie 列表</td></tr><tr><td><strong>删除 / 多选删除</strong></td><td>从当前 Cookie 配置中移除资源；仍需底部保存</td></tr></tbody></table><h3 id="添加资源" tabindex="-1">添加资源 <a class="header-anchor" href="#添加资源" aria-label="Permalink to &quot;添加资源&quot;">​</a></h3>',3)),e(d,{src:"/cms/settings/settings-cookie-add-resource-dialog.png",alt:"添加 Cookie 资源",width:"1120"}),t[11]||(t[11]=r('<table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td>可从下拉选择站点页面、布局、视图、HTML 代码块中发现的外部资源，也可手动输入</td></tr><tr><td><strong>资源类型</strong></td><td><code>script</code>、<code>img</code>、<code>iframe</code>、<code>link</code>；界面显示为脚本、图片、Iframe、链接，从下拉选择已有 URL 时会自动带出类型</td></tr><tr><td><strong>分析</strong></td><td>调用后台分析所选资源可能写入的 Cookie，并合并到 Cookie 列表；已存在同名 Cookie 不重复添加</td></tr><tr><td><strong>分类</strong></td><td>必填，从 <a href="#cookie-分类">Cookie 分类</a> 中选择</td></tr><tr><td><strong>Cookie 列表</strong></td><td>记录该资源产生的 Cookie 名称、说明与过期时间</td></tr></tbody></table><p>Cookie 项字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Cookie 名称</strong></td><td>必填，写浏览器实际 Cookie 名称</td></tr><tr><td><strong>描述</strong></td><td>多语言用途说明，展示给访客</td></tr><tr><td><strong>过期时间</strong></td><td>单位为分钟；例如 <code>60</code> 表示 1 小时，<code>1440</code> 表示 1 天</td></tr></tbody></table><h2 id="数据报表" tabindex="-1">数据报表 <a class="header-anchor" href="#数据报表" aria-label="Permalink to &quot;数据报表&quot;">​</a></h2><p>数据报表只读，不显示底部保存栏。进入 Tab 后选择日期范围查看趋势：</p><table tabindex="0"><thead><tr><th>维度</th><th>说明</th></tr></thead><tbody><tr><td><strong>决策趋势</strong></td><td>按 <strong>接受全部</strong>、<strong>拒绝全部</strong>、<strong>自定义选择</strong> 汇总</td></tr><tr><td><strong>分类趋势</strong></td><td>按 Cookie 分类汇总访客同意情况，分类名称使用当前语言</td></tr></tbody></table><p>默认日期范围为最近 7 天。若所选日期暂无统计，页面显示空态；数据来自前台访客实际提交的 Cookie 同意结果。</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><ol><li>先确认 <a href="./basic/general.html#站点信息">Base URL</a> 与 <a href="./basic/general.html#多语言">多语言</a>。</li><li>在 <strong>Cookie 分类</strong> 中维护必要分类与可选分类。</li><li>在 <strong>内容配置</strong> 中补齐每个语言的标题、说明、按钮与政策链接。</li><li>在 <strong>资源管理</strong> 中添加外部脚本、iframe、图片或 link，并绑定到对应分类。</li><li>回到 <strong>基础设置</strong>，选择显示地区、重启方式、Banner 模板并开启 Cookie 管理。</li><li>点 <strong>保存并预览</strong>，用无痕窗口或清除 Cookie 后检查首次访问、拒绝、接受所选与重新打开面板。</li><li>上线后一段时间再看 <strong>数据报表</strong>，确认访客同意趋势。</li></ol><h2 id="cms-与-api-模板引擎分工" tabindex="-1">CMS 与 API / 模板引擎分工 <a class="header-anchor" href="#cms-与-api-模板引擎分工" aria-label="Permalink to &quot;CMS 与 API / 模板引擎分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>看 CMS</th><th>看 API / 模板引擎</th></tr></thead><tbody><tr><td>配置 Cookie 同意弹窗、分类、文案、资源归类</td><td>本篇</td><td>无</td></tr><tr><td>在 KScript 中读取、设置、删除浏览器 Cookie</td><td>只说明后台已配置 Cookie 管理</td><td><a href="/kb-docs/zh/api/cookie/">k.cookie</a></td></tr><tr><td>在模板数据流中读取请求 Cookie</td><td>后台不展开模板语法</td><td><a href="/kb-docs/zh/templateEngine/k-data/tags.html#let">k-data 标签语法</a></td></tr><tr><td>给前台添加可重新打开面板的自定义按钮</td><td>本篇说明 <code>kc-reopen-btn</code> 入口</td><td><a href="./../content/tag-attributes.html">元素属性</a>、模板资源</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./">站点设置概述</a></td><td>站点设置菜单与建议配置顺序</td></tr><tr><td><a href="./basic/">基础设置</a></td><td>Base URL、多语言、站点基础开关</td></tr><tr><td><a href="./domains.html">域名管理</a></td><td>多域名与语言绑定</td></tr><tr><td><a href="/kb-docs/zh/api/cookie/">k.cookie</a></td><td>KScript Cookie 读写</td></tr><tr><td><a href="/kb-docs/zh/templateEngine/k-data/tags.html">k-data 标签语法</a></td><td>模板中从 Cookie 等请求来源读取值</td></tr></tbody></table>',13))])}const u=n(h,[["render",g]]);export{_ as __pageData,u as default};
